/**
 * Orchestrator side-effect dispatcher.
 *
 * Translates an ExecutorResult into the correct set of side effects:
 *   in_review  → mutate task YAML to in_review, append log
 *                (pr_url recorded from result.pr_url if present — executor opened it)
 *   blocked    → mutate task YAML to blocked, append log
 *                (pr_url recorded from result.pr_url if present — draft PR documents failure)
 *   failed     → mutate task YAML to blocked (executor_failed:*), append log
 *
 * Revised D5: the executor owns impl-PR creation (via /pr-create skill).
 * The orchestrator no longer opens impl PRs — it only records the pr_url
 * reported by the executor in result.json.
 *
 * Extracted from main.ts so seam tests can inject any ExecutorAdapter and
 * verify the resulting task state without running the full bootstrap + poll loop.
 */

import type { ExecutorResult } from "@workflow/runtime-abi";
import type { TaskLogEntry } from "../types/task.js";
import { mutateTaskYaml } from "./mutate-task-yaml.js";
import { mutateTaskYamlDirect } from "./mutate-task-yaml-direct.js";
import { appendLogEntry } from "./append-log.js";
import { taskBranchName } from "../paths.js";
import { tryReadTaskFromBranch } from "../task-branch-state.js";

const EXECUTOR_MAX_RETRIES = Number(process.env.EXECUTOR_MAX_RETRIES ?? "3");

export interface DispatchExecutorResultOpts {
  result: ExecutorResult;
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  taskBranch: string;
  taskTitle: string;
  taskRepoUrl: string;
  taskBaseBranch: string;
  githubToken: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  emit: (event: Record<string, unknown>) => void;
}

/**
 * Apply the side effects that correspond to an executor result.
 * Called by the orchestrator polling loop after adapter.run() returns.
 * Partially throwing: mutateTaskYaml failures are thrown so the reap loop
 * can nack the completion and retry. appendLogEntry failures are emitted but
 * swallowed — a missing log entry is non-fatal.
 */
export async function dispatchExecutorResult(
  opts: DispatchExecutorResultOpts,
): Promise<void> {
  const {
    result,
    workspaceRoot,
    featureId,
    taskId,
    taskBranch,
    gitAuthorEmail,
    gitAuthorName,
    sshKeyPath,
    emit,
  } = opts;

  // ── Max-turns retry ───────────────────────────────────────────────────────
  if (
    result.terminal_status === "blocked" &&
    typeof result.blocked_reason === "string" &&
    result.blocked_reason.startsWith("max_turns")
  ) {
    const branch = taskBranchName(featureId, taskId);
    const relPath = `docs/features/${featureId}/tasks/${taskId}.yaml`;
    const branchTask = tryReadTaskFromBranch(workspaceRoot, branch, relPath);
    if (branchTask) {
      const retriedCount = (branchTask.log ?? []).filter((e) => e.action === "retried").length;
      if (retriedCount < EXECUTOR_MAX_RETRIES) {
        const mutateErr = mutateTaskYamlDirect({
          workspaceRoot, featureId, taskId, taskBranch, status: "ready",
          logEntry: {
            action: "retried", by: gitAuthorEmail,
            note: `Max-turns block reset to ready (attempt ${retriedCount + 1} of ${EXECUTOR_MAX_RETRIES}).`,
          },
          gitAuthorEmail, gitAuthorName, sshKeyPath,
          commitMessage: `chore(${taskId}): retried — max-turns reset (${retriedCount + 1}/${EXECUTOR_MAX_RETRIES})`,
        });
        if (mutateErr) {
          emit({ type: "retry_mutate_failed", task_id: taskId, feature_id: featureId, details: mutateErr });
        } else {
          emit({ type: "task_retried", task_id: taskId, feature_id: featureId, attempt: retriedCount + 1, max: EXECUTOR_MAX_RETRIES });
          return;
        }
      } else {
        emit({ type: "task_max_retries_exceeded", task_id: taskId, feature_id: featureId, max: EXECUTOR_MAX_RETRIES });
      }
    }
  }

  // pr_url from result.json — set by executor when it opened a PR.
  // Present on any terminal_status when commits were pushed and a PR was opened.
  const prUrl = result.pr_url;

  if (result.terminal_status === "in_review") {
    if (prUrl) {
      emit({ type: "impl_pr_recorded", task_id: taskId, feature_id: featureId, pr_url: prUrl });
    }

    const mutateErr = mutateTaskYaml({
      workspaceRoot,
      featureId,
      taskId,
      taskBranch,
      result,
      prUrl,
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
    });
    if (mutateErr) {
      emit({ type: "mutate_task_yaml_failed", task_id: taskId, details: mutateErr });
      throw new Error(mutateErr);
    }

    const runCompletedEntry: Omit<TaskLogEntry, "at"> = {
      action: "run_completed",
      by: gitAuthorEmail,
      note: prUrl ? `Implementation PR: ${prUrl}` : "Implementation complete.",
      ...(result.token_usage !== undefined && { token_usage: result.token_usage }),
      ...(result.cost_usd !== undefined && { cost_usd: result.cost_usd }),
    };

    const logErr = appendLogEntry({
      workspaceRoot,
      featureId,
      taskId,
      taskBranch,
      entry: runCompletedEntry,
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
    });
    if (logErr) emit({ type: "append_log_failed", task_id: taskId, details: logErr });
  } else {
    if (prUrl) {
      emit({ type: "impl_pr_recorded", task_id: taskId, feature_id: featureId, pr_url: prUrl });
    }

    const mutateErr = mutateTaskYaml({
      workspaceRoot,
      featureId,
      taskId,
      taskBranch,
      result,
      prUrl,
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
    });
    if (mutateErr) {
      emit({ type: "mutate_task_yaml_failed", task_id: taskId, details: mutateErr });
      throw new Error(mutateErr);
    }

    const blockedEntry: Omit<TaskLogEntry, "at"> = {
      action: "blocked",
      by: gitAuthorEmail,
      note: result.blocked_reason ?? "executor returned non-in_review status",
      ...(result.token_usage !== undefined && { token_usage: result.token_usage }),
      ...(result.cost_usd !== undefined && { cost_usd: result.cost_usd }),
    };

    const logErr = appendLogEntry({
      workspaceRoot,
      featureId,
      taskId,
      taskBranch,
      entry: blockedEntry,
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
    });
    if (logErr) emit({ type: "append_log_failed", task_id: taskId, details: logErr });
  }
}

