/**
 * Git-based claim protocol for change_requested tasks (fix agent).
 */

import { execSync, spawnSync } from "node:child_process";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import { readFileSync, writeFileSync } from "node:fs";
import type { Task } from "../types/task.js";
import { taskYamlAbsPath, taskYamlRelPath, taskBranchName } from "../paths.js";
import { buildGitEnv } from "../git-env.js";

export interface ClaimFixTaskOptions {
  workspaceRoot: string;
  taskId: string;
  featureId: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  jitterMaxSeconds?: number;
  skipJitter?: boolean;
  skipGit?: boolean;
}

export type ClaimFixResult =
  | { won: true }
  | { won: false; reason: "task_not_change_requested" | "already_claimed" | "push_rejected" };

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export async function claimFixTask(opts: ClaimFixTaskOptions): Promise<ClaimFixResult> {
  const {
    workspaceRoot, taskId, featureId, gitAuthorEmail,
    gitAuthorName = gitAuthorEmail,
    jitterMaxSeconds = 0.5, skipJitter = false, skipGit = false,
  } = opts;

  const env = buildGitEnv(undefined, { email: gitAuthorEmail, name: gitAuthorName });
  const branch = taskBranchName(featureId, taskId);

  if (!skipGit) {
    try {
      execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
      execSync(`git -C "${workspaceRoot}" checkout -B "${branch}" "origin/${branch}"`, { env, stdio: "pipe" });
    } catch { return { won: false, reason: "push_rejected" }; }
  }

  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
  let task: Task;
  try { task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task; }
  catch { return { won: false, reason: "push_rejected" }; }

  if (task.status !== "change_requested") return { won: false, reason: "task_not_change_requested" };
  const last = task.log[task.log.length - 1];
  if (last?.action === "fix_started") return { won: false, reason: "already_claimed" };

  if (!skipJitter) {
    const maxMs = Math.min(jitterMaxSeconds * 1000, 500);
    await sleep(50 + Math.random() * Math.max(0, maxMs - 50));
  }

  const now = new Date().toISOString();
  task.status = "in_progress";
  task.execution.last_updated_by = gitAuthorEmail;
  task.execution.last_updated_at = now;
  task.log.push({ action: "fix_started", by: gitAuthorEmail, at: now, note: "Fix agent claimed." });
  writeFileSync(yamlPath, yamlStringify(task), "utf-8");

  if (skipGit) return { won: true };

  const relPath = taskYamlRelPath(featureId, taskId);
  try {
    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
    execSync(`git -C "${workspaceRoot}" commit -m "chore(${taskId}): fix_started — status in_progress"`, { env, stdio: "pipe" });
  } catch { return { won: false, reason: "push_rejected" }; }

  const pr = spawnSync("git", ["-C", workspaceRoot, "push", "origin", branch], { env, encoding: "utf-8" });
  return pr.status !== 0 ? { won: false, reason: "push_rejected" } : { won: true };
}

