64	/**
65	 * Returns an invokeClaudeForResolution function that pins Claude to a specific model.
66	 * Passed to all conflict-resolution handlers so they respect workspace model_policy
67	 * instead of defaulting to whatever the Claude CLI ships with.
68	 */
69	function makeConflictResolver(
70	  model: string,
71	  maxTurns = 10,
72	): (prompt: string, cwd: string, env: NodeJS.ProcessEnv) => Promise<boolean> {
73	  return (prompt, cwd, env) =>
74	    new Promise((resolve) => {
75	      const child = spawn(
76	        "claude",
77	        [
78	          "-p", prompt,
79	          "--model", model,
80	          "--max-turns", String(maxTurns),
81	          "--output-format", "stream-json",
82	          "--verbose",
83	          "--dangerously-skip-permissions",
84	        ],
85	        { cwd, env, stdio: ["ignore", "pipe", "pipe"] },
86	      );
87	      child.stdout.pipe(process.stdout);
88	      child.stderr.pipe(process.stderr);
89	      child.on("close", (code) => resolve(code === 0));
90	      child.on("error", () => resolve(false));
91	    });
92	}
