105	/** Emit a structured JSON event via the profile's EventEmitterPort. */
106	function makeEmit(ports: RuntimePorts): (event: Record<string, unknown>) => void {
107	  return (event: Record<string, unknown>) => {
108	    const { type, ...data } = event as { type?: string } & Record<string, unknown>;
109	    ports.emitter.emit(type ?? "event", data);
110	  };
111	}
