154	/**
155	 * Write a rag_pre_flight log entry to the task YAML before spawning the executor.
156	 * Commits and pushes to the task branch. Throws on error.
157	 */
158	function writeRagPreFlight(
159	  workspaceRoot: string,
160	  featureId: string,
161	  taskId: string,
162	  taskBranch: string,
163	  gitAuthorEmail: string,
164	  gitAuthorName: string,
165	  sshKeyPath: string | undefined,
166	  ragPreFlight: { query: string; injected: boolean; summary: string },
167	): void {
168	  const now = new Date().toISOString();
169	  const entry: TaskLogEntry = {
170	    action: "rag_pre_flight",
171	    by: gitAuthorEmail,
172	    at: now,
173	    rag_context_injected: ragPreFlight.injected,
174	    rag_summary: ragPreFlight.summary,
175	    rag_query: ragPreFlight.query,
176	    note: "Runtime pre-flight RAG fetch — written before executor spawn.",
177	  };
178	
179	  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
180	  const relPath = taskYamlRelPath(featureId, taskId);
181	  const gitOpts = {
182	    cwd: workspaceRoot,
183	    encoding: "utf-8" as const,
184	    env: buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName }),
185	    timeout: 30_000,
186	    stdio: "pipe" as const,
187	  };
188	
189	  // Anchor to the task branch tip before reading/writing — same pattern as
190	  // append-log and mutate-task-yaml. Defensive: claimTask leaves the repo on
191	  // the task branch, but an explicit anchor makes this function self-contained.
192	  execSync(`git fetch origin "${taskBranch}"`, gitOpts);
193	  execSync(`git checkout -B "${taskBranch}" "origin/${taskBranch}"`, gitOpts);
194	
195	  const task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
196	  task.log.push(entry);
197	  writeFileSync(yamlPath, yamlStringify(task), "utf-8");
198	
199	  execSync(`git add "${relPath}"`, gitOpts);
200	  execSync(
201	    `git commit -m "chore(${taskId}): rag pre-flight — ${ragPreFlight.injected ? "injected" : "skipped"}"`,
202	    gitOpts,
203	  );
204	  execSync(`git push origin "${taskBranch}"`, gitOpts);
205	}
