209	async function main(): Promise<number> {
210	  let agentYamlPath: string;
211	  let workflowLocalPath: string;
212	  let workspacesRoot: string;
213	  let gitAuthorEmail: string;
214	
215	  // Bootstrap-time emit — before the profile is ready, write directly to stdout.
216	  const bootstrapEmit = (event: Record<string, unknown>) => {
217	    console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
218	  };
219	
220	  try {
221	    agentYamlPath = requireEnv("AGENT_YAML_PATH");
222	    workflowLocalPath = requireEnv("WORKFLOW_LOCAL_PATH");
223	    workspacesRoot = requireEnv("WORKSPACES_ROOT");
224	    gitAuthorEmail = requireEnv("GIT_AUTHOR_EMAIL");
225	  } catch (e) {
226	    bootstrapEmit({ type: "fatal_missing_env", details: (e as Error).message });
227	    return 4;
228	  }
