230	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
231	
232	  const sshResolution = resolveSSHKey(process.env);
233	  const sshKeyPath = sshResolution.sshKeyPath;
234	
235	  // ── Create the runtime profile ────────────────────────────────────────────────
236	  // RUNTIME_PROFILE selects the adapter set. Switching profiles at startup is how
237	  // new infra is added without core changes.
238	  //   local-subprocess (default) — executor + in-process broker in one container
239	  //   local-docker               — docker run -d executor + shared Redis broker (M:N)
240	  const runtimeProfile = process.env.RUNTIME_PROFILE ?? "local-subprocess";
241	  const ports: RuntimePorts & { broker: { start(): Promise<number>; stop(): Promise<void>; getCallbackUrl(): string | null } } =
242	    runtimeProfile === "local-docker"
243	      ? createLocalDockerProfile({
244	          gitAuthorEmail,
245	          gitAuthorName,
246	          sshKeyPath,
247	          brokerUrl: process.env.BROKER_URL ?? "http://broker:7000",
248	        })
249	      : createLocalSubprocessProfile({
250	          gitAuthorEmail,
251	          gitAuthorName,
252	          sshKeyPath,
253	        });
254	
255	  // Start the broker receiver (no-op for HttpBrokerAdapter; binds HTTP port for InMemoryBrokerAdapter).
256	  const brokerPort = await ports.broker.start();
257	
258	  const emit = makeEmit(ports);
259	  emit({ type: "broker_started", port: brokerPort, callback_url: ports.broker.getCallbackUrl() });
260	
261	  if (sshResolution.warned) {
262	    emit({ type: "warn_no_ssh_key", note: "SSH_PRIVATE_KEY is not set — git operations over SSH will fail." });
263	  }
264	
265	  const bootstrapResult = await runBootstrap({
266	    agentYamlPath,
267	    workflowLocalPath,
268	    workflowUrl: process.env.WORKFLOW_URL,
269	    workspacesRoot,
270	    sshKeyPath,
271	  });
272	
273	  if (bootstrapResult.exitCode !== 0) return bootstrapResult.exitCode;
274	
275	  const config = bootstrapResult.config!;
276	  const githubToken = process.env.GITHUB_TOKEN ?? "";
277	  if (!githubToken) emit({ type: "warn_no_github_token" });
