279	  // ── Feature Branch Lifecycle Manager (T8) ────────────────────────────────────
280	  // Runs once at startup — creates or syncs feature/{featureId} on each watched
281	  // workspace before the main dispatch loop begins.
282	  for (const watchUrl of config.watches) {
283	    const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
284	    if (!existsSync(workspaceLocalPath)) continue;
285	    try {
286	      const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
287	      runFeatureBranchLifecycle({
288	        workspaceRoot: workspaceLocalPath,
289	        baseBranch: mgmtCoords.baseBranch,
290	        gitAuthorEmail,
291	        gitAuthorName,
292	        sshKeyPath,
293	        emit,
294	      });
295	    } catch (e) {
296	      emit({ type: "feature_branch_lifecycle_workspace_error", workspace: watchUrl, details: String(e) });
297	    }
298	  }
