300	  let lastPrPollAt: number | null = null;
301	  // Local counter for local-docker mode — tracks how many executor containers are
302	  // in-flight. Incremented on submit, decremented when the reap loop acks a completion.
303	  // TODO: replace with broker.registrySize() once the broker exposes that endpoint.
304	  let dockerInFlight = 0;
305	
306	  async function buildAndSubmitExecutor(opts: {
307	    task: Task;
308	    featureId: string;
309	    workspaceId: string;
310	    taskRepoUrl: string;
311	    taskBranch: string;
312	    taskRepoRoot: string;
313	    implementationModel: string;
