341	    const extraEnv: Record<string, string> = {
342	      WORKSPACE_ROOT: workspaceLocalPath,
343	      TASK_BRANCH: taskBranch,
344	      GIT_AUTHOR_EMAIL: gitAuthorEmail,
345	      GIT_AUTHOR_NAME: gitAuthorName,
346	      WORKFLOW_LOCAL_PATH: workflowLocalPath,
347	      MAX_TURNS: String(config.budget.max_iterations),
348	      LOG_SINK_ENABLED: config.log_sink.enabled ? "1" : "0",
349	      ...(process.env.MCP_RAG_URL ? { MCP_RAG_URL: process.env.MCP_RAG_URL } : {}),
350	      ...(process.env.FIGMA_PERSONAL_ACCESS_TOKEN
351	        ? { FIGMA_PERSONAL_ACCESS_TOKEN: process.env.FIGMA_PERSONAL_ACCESS_TOKEN }
352	        : {}),
353	    };
