369	  async function runOneCycle(): Promise<CycleOutcome> {
370	    // In local-subprocess mode all repos share the same container filesystem.
371	    // If an executor is running, skip impl repo pulls — syncRepo would switch
372	    // the shared working tree to the base branch and hard-reset it, destroying
373	    // any uncommitted work the executor has in flight.
374	    const execInFlight =
375	      runtimeProfile === "local-subprocess"
376	        ? (ports.broker as InMemoryBrokerAdapter).registrySize() > 0
377	        : false;
378	
379	    const pullResults = pullWorkspaces({
380	      watchUrls: config.watches,
381	      sshKeyPath,
382	      workspacesRoot,
383	      workflowUrl: process.env.WORKFLOW_URL,
384	      workflowLocalPath,
385	      skipImplRepoPull: execInFlight,
386	      emit,
387	    });
388	
389	    const haltedUrls = new Set(
390	      pullResults
391	        .filter((r) => r.outcome === "halt" || r.outcome === "warn")
392	        .map((r) => r.url),
393	    );
394	
395	    let outcome: CycleOutcome = "idle";
396	    const pulledWorkspaceRoots: string[] = [];
397	
398	    // ── Subprocess concurrency guard + task dispatch ──────────────────────────
399	    // In local-subprocess mode all repos share the same container filesystem.
400	    // Two concurrent subprocesses can race on git checkouts in the same repo.
401	    // Wrap the dispatch loop in a labeled block so we can break out of it
402	    // (skipping to PR poll + reap) when a subprocess is already in-flight.
403	    dispatchBlock: {
404	      const defaultMax = runtimeProfile === "local-subprocess" ? 1 : 4;
405	      const maxConcurrent = config.max_concurrent_executors ?? defaultMax;
406	
407	      if (runtimeProfile === "local-subprocess") {
408	        const inFlight = (ports.broker as InMemoryBrokerAdapter).registrySize();
409	        if (inFlight >= maxConcurrent) {
410	          emit({ type: "executor_pool_full", in_flight: inFlight, max: maxConcurrent });
411	          break dispatchBlock;
412	        }
413	      } else if (runtimeProfile === "local-docker") {
414	        if (dockerInFlight >= maxConcurrent) {
415	          emit({ type: "executor_pool_full", in_flight: dockerInFlight, max: maxConcurrent });
416	          break dispatchBlock;
417	        }
418	      }
419	
420	    outerLoop:
421	    for (const watchUrl of config.watches) {
422	      if (haltedUrls.has(watchUrl)) continue;
423	
424	      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
425	      pulledWorkspaceRoots.push(workspaceLocalPath);
426	
427	      if (!existsSync(workspaceLocalPath)) {
428	        emit({ type: "workspace_not_found", workspace_url: watchUrl });
429	        continue;
430	      }
431	
432	      let eligibleTasks;
433	      try {
434	        eligibleTasks = findEligibleTasks(config, workspaceLocalPath, workflowLocalPath);
435	      } catch (e) {
436	        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
437	        continue;
438	      }
439	
440	      if (eligibleTasks.length === 0) {
441	        emit({ type: "no_eligible_tasks", workspace_url: watchUrl });
442	        continue;
443	      }
444	
445	      for (const { task, featureId } of eligibleTasks) {
446	        const claimResult = await claimTask({
447	          workspaceRoot: workspaceLocalPath,
448	          taskId: task.id,
449	          featureId,
450	          gitAuthorEmail,
451	          gitAuthorName,
452	          sshKeyPath,
453	          jitterMaxSeconds: config.jitter_max_seconds,
454	        });
455	
456	        const taskBranch = taskBranchName(featureId, task.id);
457	
458	        if (!claimResult.won) {
459	          if (claimResult.reason !== "branch_blocked_recovery") {
460	            emit({ type: "claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
461	            continue;
462	          }
463	          emit({ type: "task_blocked_recovery_detected", task_id: task.id, feature_id: featureId });
464	        } else {
465	          emit({ type: "task_claimed", task_id: task.id, feature_id: featureId });
466	        }
467	
468	        // ── Open management-repo PR ───────────────────────────────────────────
469	        if (githubToken) {
470	          try {
471	            const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
472	            await openWorkspacePr({
473	              workspaceRoot: workspaceLocalPath,
474	              featureId,
475	              taskId: task.id,
476	              branch: taskBranch,
477	              // Task PRs target the feature branch so all task changes collect
478	              // there before the Handoff Trigger merges to the base branch (T8).
479	              baseBranch: featureBranchName(featureId),
480	              githubToken,
481	              repoOwner: mgmtCoords.owner,
482	              repoName: mgmtCoords.repo,
483	              gitAuthorEmail,
484	              gitAuthorName,
485	              sshKeyPath,
486	            });
487	            emit({ type: "workspace_pr_opened", task_id: task.id, feature_id: featureId });
488	          } catch (e) {
489	            const stderr = (e as { stderr?: Buffer | string }).stderr;
490	            const stderrStr = stderr instanceof Buffer ? stderr.toString("utf-8") : (stderr ?? "");
491	            emit({ type: "workspace_pr_failed", task_id: task.id, feature_id: featureId, details: String(e), stderr: stderrStr });
492	          }
493	        }
494	
495	        // ── Resolve model + task repo ────────────────────────────────────────
496	        const { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel } =
497	          resolveTaskContext(workspaceLocalPath, featureId, task);
498	
499	        // ── RAG pre-flight ───────────────────────────────────────────────────
500	        const mcpRagUrl = process.env.MCP_RAG_URL;
501	        const workspaceYaml = parseYaml(
502	          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
503	        ) as { workspace_id: string };
504	        const ragQuery = `${task.title} ${featureId}`;
505	        const ragPreFlight = await fetchRagContext(mcpRagUrl, ragQuery, workspaceYaml.workspace_id);
506	
507	        try {
508	          writeRagPreFlight(
509	            workspaceLocalPath,
510	            featureId,
511	            task.id,
512	            taskBranch,
513	            gitAuthorEmail,
514	            gitAuthorName,
515	            sshKeyPath,
516	            { query: ragQuery, injected: ragPreFlight.injected, summary: ragPreFlight.summary },
517	          );
518	        } catch (e) {
519	          const details = String(e);
520	          emit({ type: "rag_pre_flight_failed", task_id: task.id, feature_id: featureId, details });
521	          mutateTaskYaml({
522	            workspaceRoot: workspaceLocalPath,
523	            featureId,
524	            taskId: task.id,
525	            taskBranch,
526	            result: { terminal_status: "failed", blocked_reason: `rag_pre_flight_error: ${details}` },
527	            gitAuthorEmail,
528	            gitAuthorName,
529	            sshKeyPath,
530	          });
531	          continue;
532	        }
533	
534	        // ── Generate briefing ────────────────────────────────────────────────
535	        const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
536	        const baseContext = generateBriefing({
537	          taskId: task.id,
538	          featureId,
539	          taskTitle: task.title,
540	          taskBranch,
541	          taskRepo: task.repo,
542	          taskRepoRoot,
543	          workspaceRoot: workspaceLocalPath,
544	          gitAuthorEmail,
545	          gitAuthorName,
546	          implementationModel,
547	          resultPath,
548	        });
549	        const briefingContent = ragPreFlight.block
550	          ? `${baseContext}\n\n${ragPreFlight.block}`
551	          : baseContext;
552	
553	        // ── Write briefing via BriefingTransportPort ─────────────────────────
554	        // Use taskId as the briefing handle so the file path matches the
555	        // existing briefing-{taskId}/briefing.md convention.
556	        const briefingPath = await ports.briefing.put(task.id, briefingContent);
557	
558	        // ── Submit executor (async — T6) ─────────────────────────────────────
559	        const execHandle = await buildAndSubmitExecutor({
560	          task, featureId, workspaceId: workspaceYaml.workspace_id,
561	          taskRepoUrl, taskBranch, taskRepoRoot, implementationModel,
562	          briefingPath, resultPath, workspaceLocalPath,
563	        });
564	
565	        // Persist handle to task YAML for broker crash-recovery reconciliation.
566	        try {
567	          await ports.workflowState.persistHandle(workspaceLocalPath, featureId, task.id, execHandle);
568	        } catch (e) {
569	          emit({ type: "persist_handle_failed", task_id: task.id, feature_id: featureId, details: String(e) });
570	        }
571	
572	        emit({ type: "executor_submitted", task_id: task.id, feature_id: featureId, handle: execHandle });
573	        if (runtimeProfile === "local-docker") dockerInFlight++;
574	        outcome = "ran_task";
575	        break outerLoop;
576	      }
577	    }
578	
579	    // ── Fix-agent dispatch ────────────────────────────────────────────────────
580	    if (outcome !== "ran_task") {
581	      fixLoop:
582	      for (const watchUrl of config.watches) {
583	        if (haltedUrls.has(watchUrl)) continue;
584	
585	        const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
586	        if (!existsSync(workspaceLocalPath)) continue;
587	
588	        let fixableTasks;
589	        try {
590	          fixableTasks = findFixableTasks(config, workspaceLocalPath);
591	        } catch (e) {
592	          emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
593	          continue;
594	        }
595	
596	        for (const { task, featureId } of fixableTasks) {
597	          const taskBranch = taskBranchName(featureId, task.id);
598	          const claimResult = await claimFixTask({
599	            workspaceRoot: workspaceLocalPath,
600	            taskId: task.id,
601	            featureId,
602	            gitAuthorEmail,
603	            gitAuthorName,
604	            jitterMaxSeconds: config.jitter_max_seconds,
605	          });
606	
607	          if (!claimResult.won) {
608	            emit({ type: "fix_claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
609	            continue;
610	          }
611	
612	          emit({ type: "fix_task_claimed", task_id: task.id, feature_id: featureId });
613	
614	          const { taskRepoRoot, taskRepoUrl, implementationModel } = resolveTaskContext(workspaceLocalPath, featureId, task);
615	          const fixWsYaml = parseYaml(
616	            readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
617	          ) as { workspace_id: string };
618	
619	          const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
620	          const baseContext = generateBriefing({
621	            taskId: task.id,
622	            featureId,
623	            taskTitle: task.title,
624	            taskBranch,
625	            taskRepo: task.repo,
626	            taskRepoRoot,
627	            workspaceRoot: workspaceLocalPath,
628	            gitAuthorEmail,
629	            gitAuthorName,
630	            implementationModel,
631	            resultPath,
632	          });
633	
634	          const fixBriefingPath = await ports.briefing.put(task.id, baseContext);
635	          const fixHandle = await buildAndSubmitExecutor({
636	            task, featureId, workspaceId: fixWsYaml.workspace_id,
637	            taskRepoUrl, taskBranch, taskRepoRoot: taskRepoRoot, implementationModel,
638	            briefingPath: fixBriefingPath, resultPath, workspaceLocalPath,
639	          });
640	          emit({ type: "fix_executor_submitted", task_id: task.id, feature_id: featureId, handle: fixHandle });
641	          if (runtimeProfile === "local-docker") dockerInFlight++;
642	          outcome = "ran_task";
643	          break fixLoop;
644	        }
645	      }
646	    }
647	
648	    // ── Reviewer dispatch ─────────────────────────────────────────────────────
649	    if (outcome !== "ran_task") {
650	      reviewerLoop:
651	      for (const watchUrl of config.watches) {
652	        if (haltedUrls.has(watchUrl)) continue;
653	
654	        const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
655	        if (!existsSync(workspaceLocalPath)) continue;
656	
657	        let reviewableTasks;
658	        try {
659	          reviewableTasks = findReviewableTasks(config, workspaceLocalPath);
660	        } catch (e) {
661	          emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
662	          continue;
663	        }
664	
665	        for (const { task, featureId } of reviewableTasks) {
666	          const taskBranch = taskBranchName(featureId, task.id);
667	          const { taskRepoRoot, taskRepoUrl, implementationModel } = resolveTaskContext(workspaceLocalPath, featureId, task);
668	          const wsModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
669	          const revWsYaml = parseYaml(
670	            readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
671	          ) as { workspace_id: string };
672	          let reviewModelOverrides = {};
673	          try {
674	            const tMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
675	            reviewModelOverrides = parseModelOverrides(readFileSync(tMdPath, "utf-8"), task.id);
676	          } catch { /* non-fatal */ }
677	          const reviewerModel = resolveModel(wsModelPolicy, reviewModelOverrides, "self_review", task.id);
678	
679	          const dispatchResult = await dispatchReviewer({
680	            workspaceRoot: workspaceLocalPath,
681	            featureId,
682	            taskId: task.id,
683	            taskBranch,
684	            implRepoRoot: taskRepoRoot,
685	            implRepoUrl: taskRepoUrl,
686	            gitAuthorEmail,
687	            gitAuthorName,
688	            workflowLocalPath,
689	            maxTurns: config.budget.max_iterations,
690	            maxTokens: config.budget.max_tokens_per_task,
691	            logSinkEnabled: config.log_sink.enabled,
692	            reviewerModel,
693	            workspaceId: revWsYaml.workspace_id,
694	            githubToken,
695	            broker: ports.broker,
696	            callbackUrl: ports.broker.getCallbackUrl() ?? "",
697	            emit,
698	          });
699	
700	          if (dispatchResult === "dispatched") {
701	            if (runtimeProfile === "local-docker") dockerInFlight++;
702	            outcome = "ran_task";
703	            break reviewerLoop;
704	          }
705	        }
706	      }
707	    }
708	    } // end dispatchBlock
709	
710	    // ── In-review PR poll ─────────────────────────────────────────────────────
711	    // In local-subprocess mode the executor subprocess shares the same container
712	    // filesystem as the orchestrator. Both can race on `git rebase` in the same
713	    // repo — a second rebase operation fails with "rebase-merge directory already
714	    // exists". Re-check in-flight count here (not just in dispatchBlock) because
715	    // pulledWorkspaceRoots is already populated on the same cycle that dispatched
716	    // the executor; the dispatchBlock early-break only fires on *subsequent* cycles.
717	    const skipPrPoll =
718	      runtimeProfile === "local-subprocess" &&
719	      (ports.broker as InMemoryBrokerAdapter).registrySize() > 0;
720	    if (githubToken && !skipPrPoll) {
721	      const prPollIntervalMs =
722	        (config.pr_poll_interval_seconds ?? config.idle_sleep_seconds ?? 60) * 1000;
723	      const now = Date.now();
724	
725	      if (lastPrPollAt === null || now - lastPrPollAt >= prPollIntervalMs) {
726	        if (pulledWorkspaceRoots.length > 0) lastPrPollAt = now;
727	        try {
728	          const { prResults, workspacePrRecoveries } = await checkInReviewPrs({
729	            workspaceRoots: pulledWorkspaceRoots,
730	            githubToken,
731	            emit,
732	          });
733	
734	          for (const wsRoot of pulledWorkspaceRoots) {
735	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
736	            if (wsResults.some((r) => r.mergeable === false)) {
737	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
738	              const conflictModel = resolveModel(wsModelPolicy, {}, "conflict_resolution", "conflict-resolver");
739	              await handleMergeConflicts({
740	                prResults: wsResults,
741	                workspaceRoot: wsRoot,
742	                resolveImplRepoRoot: (repoId) => resolveRepoLocalPath(wsRoot, repoId),
743	                resolveImplBaseBranch: (repoId) => resolveRepoBaseBranch(wsRoot, repoId),
744	                resolveTaskRepoId: (fId, tId) => resolveTaskRepoId(wsRoot, fId, tId),
745	                gitAuthorEmail,
746	                gitAuthorName,
747	                sshKeyPath,
748	                emit,
749	                invokeClaudeForResolution: makeConflictResolver(conflictModel),
750	              });
751	            }
752	          }
753	
754	          for (const wsRoot of pulledWorkspaceRoots) {
755	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
756	            if (wsResults.some((r) => r.merged === true)) {
757	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
758	              const conflictModel = resolveModel(wsModelPolicy, {}, "conflict_resolution", "conflict-resolver");
759	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
760	              await handleMergedPrs({
761	                prResults: wsResults,
762	                workspaceRoot: wsRoot,
763	                mgmtRepoOwner: mgmtCoords.owner,
764	                mgmtRepoName: mgmtCoords.repo,
765	                mgmtBaseBranch: mgmtCoords.baseBranch,
766	                githubToken,
767	                gitAuthorEmail,
768	                gitAuthorName,
769	                sshKeyPath,
770	                emit,
771	                invokeClaudeForResolution: makeConflictResolver(conflictModel),
772	              });
773	            }
774	          }
775	
776	          for (const wsRoot of pulledWorkspaceRoots) {
777	            const wsRecoveries = workspacePrRecoveries.filter((r) => r.workspaceRoot === wsRoot);
778	            if (wsRecoveries.length > 0) {
779	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
780	              const conflictModel = resolveModel(wsModelPolicy, {}, "conflict_resolution", "conflict-resolver");
781	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
782	              await handleWorkspacePrRecoveries({
783	                recoveries: wsRecoveries,
784	                mgmtRepoOwner: mgmtCoords.owner,
785	                mgmtRepoName: mgmtCoords.repo,
786	                mgmtBaseBranch: mgmtCoords.baseBranch,
787	                githubToken,
788	                gitAuthorEmail,
789	                gitAuthorName,
790	                sshKeyPath,
791	                emit,
792	                invokeClaudeForResolution: makeConflictResolver(conflictModel),
793	              });
794	            }
795	          }
796	        } catch (e) {
797	          emit({ type: "in_review_poll_error", details: String(e) });
798	        }
799	      }
800	    }
801	
802	    // ── Shared reap loop ──────────────────────────────────────────────────────
803	    // Drain completions posted by in-flight executors this cycle (and any
804	    // leftovers from previous cycles). Routes by handle.kind → dispatcher.
805	    try {
806	      const reapResult = await runReapLoop({
807	        broker: ports.broker,
808	        workspaceRoots: pulledWorkspaceRoots,
809	        gitAuthorEmail,
810	        gitAuthorName,
811	        sshKeyPath,
812	        githubToken,
813	        emit,
814	      });
815	      if (reapResult.dispatched > 0) {
816	        if (runtimeProfile === "local-docker") {
817	          dockerInFlight = Math.max(0, dockerInFlight - reapResult.dispatched);
818	        }
819	        emit({ type: "reap_cycle_complete", dispatched: reapResult.dispatched, failed: reapResult.failed });
820	        if (outcome === "idle") outcome = "ran_task";
821	      }
822	    } catch (e) {
823	      emit({ type: "reap_loop_error", details: String(e) });
824	    }
825	
826	    return outcome;
827	  }
828	
829	  await runAgentLoop({ config, runCycle: runOneCycle, emit, scheduler: ports.scheduler });
830	  return 0;
831	}
832	
833	main()
834	  .then((code) => process.exit(code))
835	  .catch((e) => {
836	    try {
837	      console.log(JSON.stringify({
838	        type: "fatal_error",
839	        details: (e as Error).message ?? String(e),
840	        at: new Date().toISOString(),
841	      }));
842	    } catch { /* last resort */ }
843	    process.exit(4);
844	  });
