/**
 * Orchestrator main entry point.
 *
 * Lifecycle:
 *   bootstrap (once) → polling loop:
 *     pull workspaces → eligibility → claim → briefing → adapter.run →
 *     side-effects → sleep → repeat
 *
 * idle_sleep_seconds controls loop behaviour (read from agent.yaml):
 *   0   → single-shot mode: one cycle then exit
 *   >0  → continuous: loops indefinitely, sleeping idle_sleep_seconds between cycles
 *
 * Exit codes:
 *   0  normal exit
 *   2  agent.yaml invalid
 *   3  git clone/pull failed (bootstrap only)
 *   4  unexpected fatal error
 */

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { execSync, spawn } from "node:child_process";
import { randomUUID } from "node:crypto";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import { runBootstrap } from "./bootstrap/bootstrap.js";
import { resolveSSHKey } from "./resolve-ssh-key.js";
import { workspaceYamlPath, taskYamlAbsPath, taskYamlRelPath, taskBranchName, featureBranchName } from "./paths.js";
import { runFeatureBranchLifecycle } from "./feature-branch/lifecycle-manager.js";
import { findEligibleTasks, findFixableTasks, findReviewableTasks } from "./eligibility/match.js";
import { claimTask } from "./claim/claim-task.js";
import { claimFixTask } from "./claim/claim-fix-task.js";
import { openWorkspacePr } from "./claim/open-workspace-pr.js";
import type { Task, TaskLogEntry } from "./types/task.js";
import { generateBriefing } from "./briefing/agent-context.js";
import { generateFixBriefing, extractPrUrlFromTask } from "./briefing/fix-briefing.js";
import { fetchRagContext } from "./bootstrap/fetch-rag-context.js";
import { resolveModel } from "./config/resolve-model-policy.js";
import { parseModelOverrides } from "./config/parse-model-overrides.js";
import {
  resolveRepoLocalPath,
  resolveRepoBaseBranch,
  resolveRepoGitUrl,
  loadWorkspaceModelPolicy,
  parseManagementRepoCoords,
} from "./config/workspace-config.js";
import { pullWorkspaces } from "./poll/pull-workspaces.js";
import { runAgentLoop, type CycleOutcome } from "./poll/agent-loop.js";
import { runReapLoop } from "./poll/reap-loop.js";
import { checkInReviewPrs } from "./poll/check-in-review-prs.js";
import { handleMergeConflicts } from "./pr-response/auto-rebase.js";
import { dispatchReviewer } from "./pr-response/dispatch-reviewer.js";
import { handleMergedPrs, handleWorkspacePrRecoveries } from "./poll/handle-merged-prs.js";
import type { ExecutorPortInput } from "@workflow/runtime-abi";
import { buildGitEnv } from "./git-env.js";
import { mutateTaskYaml } from "./side-effects/mutate-task-yaml.js";
import { createLocalSubprocessProfile } from "./profiles/local-subprocess.js";
import { createLocalDockerProfile } from "./profiles/local-docker.js";
import type { RuntimePorts } from "./runtime-ports.js";
import { SubProcessAdapter } from "./adapters/executor/subprocess.js";
import { InMemoryBrokerAdapter } from "./adapters/broker/in-memory.js";

// ── Helpers ───────────────────────────────────────────────────────────────────

/**
 * Returns an invokeClaudeForResolution function that pins Claude to a specific model.
 * Passed to all conflict-resolution handlers so they respect workspace model_policy
 * instead of defaulting to whatever the Claude CLI ships with.
 */
function makeConflictResolver(
  model: string,
  maxTurns = 10,
): (prompt: string, cwd: string, env: NodeJS.ProcessEnv) => Promise<boolean> {
  return (prompt, cwd, env) =>
    new Promise((resolve) => {
      const child = spawn(
        "claude",
        [
          "-p", prompt,
          "--model", model,
          "--max-turns", String(maxTurns),
          "--output-format", "stream-json",
          "--verbose",
          "--dangerously-skip-permissions",
        ],
        { cwd, env, stdio: ["ignore", "pipe", "pipe"] },
      );
      child.stdout.pipe(process.stdout);
      child.stderr.pipe(process.stderr);
      child.on("close", (code) => resolve(code === 0));
      child.on("error", () => resolve(false));
    });
}

function requireEnv(name: string): string {
  const val = process.env[name];
  if (!val) throw new Error(`Required environment variable ${name} is not set`);
  return val;
}

function extractRepoName(url: string): string {
  const match = /\/([^/]+?)(?:\.git)?$/.exec(url);
  return match?.[1] ?? url;
}

/** Emit a structured JSON event via the profile's EventEmitterPort. */
function makeEmit(ports: RuntimePorts): (event: Record<string, unknown>) => void {
  return (event: Record<string, unknown>) => {
    const { type, ...data } = event as { type?: string } & Record<string, unknown>;
    ports.emitter.emit(type ?? "event", data);
  };
}

function resolveTaskRepoId(workspaceRoot: string, featureId: string, taskId: string): string {
  const task = parseYaml(
    readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
  ) as { repo: string };
  if (!task.repo) throw new Error(`Task ${taskId} has no repo field`);
  return task.repo;
}

interface TaskContext {
  taskRepoRoot: string;
  taskRepoUrl: string;
  taskBaseBranch: string;
  implementationModel: string;
}

function resolveTaskContext(
  workspaceLocalPath: string,
  featureId: string,
  task: Task,
): TaskContext {
  const workspaceModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
  const taskRepoRoot = resolveRepoLocalPath(workspaceLocalPath, task.repo);
  const taskRepoUrl = resolveRepoGitUrl(workspaceLocalPath, task.repo);
  const taskBaseBranch = resolveRepoBaseBranch(workspaceLocalPath, task.repo);

  const tasksMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
  let taskModelOverrides = {};
  try {
    taskModelOverrides = parseModelOverrides(readFileSync(tasksMdPath, "utf-8"), task.id);
  } catch { /* non-fatal */ }

  const implementationModel = resolveModel(
    workspaceModelPolicy,
    taskModelOverrides,
    "implementation",
    task.id,
  );

  return { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel };
}

/**
 * Write a rag_pre_flight log entry to the task YAML before spawning the executor.
 * Commits and pushes to the task branch. Throws on error.
 */
function writeRagPreFlight(
  workspaceRoot: string,
  featureId: string,
  taskId: string,
  taskBranch: string,
  gitAuthorEmail: string,
  gitAuthorName: string,
  sshKeyPath: string | undefined,
  ragPreFlight: { query: string; injected: boolean; summary: string },
): void {
  const now = new Date().toISOString();
  const entry: TaskLogEntry = {
    action: "rag_pre_flight",
    by: gitAuthorEmail,
    at: now,
    rag_context_injected: ragPreFlight.injected,
    rag_summary: ragPreFlight.summary,
    rag_query: ragPreFlight.query,
    note: "Runtime pre-flight RAG fetch — written before executor spawn.",
  };

  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
  const relPath = taskYamlRelPath(featureId, taskId);
  const gitOpts = {
    cwd: workspaceRoot,
    encoding: "utf-8" as const,
    env: buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName }),
    timeout: 30_000,
    stdio: "pipe" as const,
  };

  // Anchor to the task branch tip before reading/writing — same pattern as
  // append-log and mutate-task-yaml. Defensive: claimTask leaves the repo on
  // the task branch, but an explicit anchor makes this function self-contained.
  execSync(`git fetch origin "${taskBranch}"`, gitOpts);
  execSync(`git checkout -B "${taskBranch}" "origin/${taskBranch}"`, gitOpts);

  const task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
  task.log.push(entry);
  writeFileSync(yamlPath, yamlStringify(task), "utf-8");

  execSync(`git add "${relPath}"`, gitOpts);
  execSync(
    `git commit -m "chore(${taskId}): rag pre-flight — ${ragPreFlight.injected ? "injected" : "skipped"}"`,
    gitOpts,
  );
  execSync(`git push origin "${taskBranch}"`, gitOpts);
}

// ── Main ──────────────────────────────────────────────────────────────────────

async function main(): Promise<number> {
  let agentYamlPath: string;
  let workflowLocalPath: string;
  let workspacesRoot: string;
  let gitAuthorEmail: string;

  // Bootstrap-time emit — before the profile is ready, write directly to stdout.
  const bootstrapEmit = (event: Record<string, unknown>) => {
    console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
  };

  try {
    agentYamlPath = requireEnv("AGENT_YAML_PATH");
    workflowLocalPath = requireEnv("WORKFLOW_LOCAL_PATH");
    workspacesRoot = requireEnv("WORKSPACES_ROOT");
    gitAuthorEmail = requireEnv("GIT_AUTHOR_EMAIL");
  } catch (e) {
    bootstrapEmit({ type: "fatal_missing_env", details: (e as Error).message });
    return 4;
  }

  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;

  const sshResolution = resolveSSHKey(process.env);
  const sshKeyPath = sshResolution.sshKeyPath;

  // ── Create the runtime profile ────────────────────────────────────────────────
  // RUNTIME_PROFILE selects the adapter set. Switching profiles at startup is how
  // new infra is added without core changes.
  //   local-subprocess (default) — executor + in-process broker in one container
  //   local-docker               — docker run -d executor + shared Redis broker (M:N)
  const runtimeProfile = process.env.RUNTIME_PROFILE ?? "local-subprocess";
  const ports: RuntimePorts & { broker: { start(): Promise<number>; stop(): Promise<void>; getCallbackUrl(): string | null } } =
    runtimeProfile === "local-docker"
      ? createLocalDockerProfile({
          gitAuthorEmail,
          gitAuthorName,
          sshKeyPath,
          brokerUrl: process.env.BROKER_URL ?? "http://broker:7000",
        })
      : createLocalSubprocessProfile({
          gitAuthorEmail,
          gitAuthorName,
          sshKeyPath,
        });

  // Start the broker receiver (no-op for HttpBrokerAdapter; binds HTTP port for InMemoryBrokerAdapter).
  const brokerPort = await ports.broker.start();

  const emit = makeEmit(ports);
  emit({ type: "broker_started", port: brokerPort, callback_url: ports.broker.getCallbackUrl() });

  if (sshResolution.warned) {
    emit({ type: "warn_no_ssh_key", note: "SSH_PRIVATE_KEY is not set — git operations over SSH will fail." });
  }

  const bootstrapResult = await runBootstrap({
    agentYamlPath,
    workflowLocalPath,
    workflowUrl: process.env.WORKFLOW_URL,
    workspacesRoot,
    sshKeyPath,
  });

  if (bootstrapResult.exitCode !== 0) return bootstrapResult.exitCode;

  const config = bootstrapResult.config!;
  const githubToken = process.env.GITHUB_TOKEN ?? "";
  if (!githubToken) emit({ type: "warn_no_github_token" });

  // ── Feature Branch Lifecycle Manager (T8) ────────────────────────────────────
  // Runs once at startup — creates or syncs feature/{featureId} on each watched
  // workspace before the main dispatch loop begins.
  for (const watchUrl of config.watches) {
    const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
    if (!existsSync(workspaceLocalPath)) continue;
    try {
      const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
      runFeatureBranchLifecycle({
        workspaceRoot: workspaceLocalPath,
        baseBranch: mgmtCoords.baseBranch,
        gitAuthorEmail,
        gitAuthorName,
        sshKeyPath,
        emit,
      });
    } catch (e) {
      emit({ type: "feature_branch_lifecycle_workspace_error", workspace: watchUrl, details: String(e) });
    }
  }

  let lastPrPollAt: number | null = null;
  // Local counter for local-docker mode — tracks how many executor containers are
  // in-flight. Incremented on submit, decremented when the reap loop acks a completion.
  // TODO: replace with broker.registrySize() once the broker exposes that endpoint.
  let dockerInFlight = 0;

  async function buildAndSubmitExecutor(opts: {
    task: Task;
    featureId: string;
    workspaceId: string;
    taskRepoUrl: string;
    taskBranch: string;
    taskRepoRoot: string;
    implementationModel: string;
    briefingPath: string;
    resultPath: string;
    workspaceLocalPath: string;
  }) {
    const { task, featureId, workspaceId, taskRepoUrl, taskBranch, taskRepoRoot,
            implementationModel, briefingPath, resultPath, workspaceLocalPath } = opts;

    const nonce = randomUUID();
    const callbackUrl = ports.broker.getCallbackUrl() ?? "";

    const execInput: ExecutorPortInput = {
      taskId: task.id,
      featureId,
      workspaceId,
      taskRepoUrl,
      taskRepoBranch: taskBranch,
      taskRepoPath: taskRepoRoot,
      briefingPath,
      resultPath,
      budgetTokens: config.budget.max_tokens_per_task,
      implementationModel,
      sshPrivateKey: process.env.SSH_PRIVATE_KEY ?? "",
      githubToken,
      callbackUrl,
      nonce,
    };

    const extraEnv: Record<string, string> = {
      WORKSPACE_ROOT: workspaceLocalPath,
      TASK_BRANCH: taskBranch,
      GIT_AUTHOR_EMAIL: gitAuthorEmail,
      GIT_AUTHOR_NAME: gitAuthorName,
      WORKFLOW_LOCAL_PATH: workflowLocalPath,
      MAX_TURNS: String(config.budget.max_iterations),
      LOG_SINK_ENABLED: config.log_sink.enabled ? "1" : "0",
      ...(process.env.MCP_RAG_URL ? { MCP_RAG_URL: process.env.MCP_RAG_URL } : {}),
      ...(process.env.FIGMA_PERSONAL_ACCESS_TOKEN
        ? { FIGMA_PERSONAL_ACCESS_TOKEN: process.env.FIGMA_PERSONAL_ACCESS_TOKEN }
        : {}),
    };

    const adapter =
      runtimeProfile === "local-docker"
        ? new (await import("./adapters/executor/docker-run.js")).DockerRunAdapter({
            broker: ports.broker,
            extraEnv,
          })
        : new SubProcessAdapter({
            broker: ports.broker,
            extraEnv,
          });

    return adapter.submit(execInput);
  }

  async function runOneCycle(): Promise<CycleOutcome> {
    // In local-subprocess mode all repos share the same container filesystem.
    // If an executor is running, skip impl repo pulls — syncRepo would switch
    // the shared working tree to the base branch and hard-reset it, destroying
    // any uncommitted work the executor has in flight.
    const execInFlight =
      runtimeProfile === "local-subprocess"
        ? (ports.broker as InMemoryBrokerAdapter).registrySize() > 0
        : false;

    const pullResults = pullWorkspaces({
      watchUrls: config.watches,
      sshKeyPath,
      workspacesRoot,
      workflowUrl: process.env.WORKFLOW_URL,
      workflowLocalPath,
      skipImplRepoPull: execInFlight,
      emit,
    });

    const haltedUrls = new Set(
      pullResults
        .filter((r) => r.outcome === "halt" || r.outcome === "warn")
        .map((r) => r.url),
    );

    let outcome: CycleOutcome = "idle";
    const pulledWorkspaceRoots: string[] = [];

    // ── Subprocess concurrency guard + task dispatch ──────────────────────────
    // In local-subprocess mode all repos share the same container filesystem.
    // Two concurrent subprocesses can race on git checkouts in the same repo.
    // Wrap the dispatch loop in a labeled block so we can break out of it
    // (skipping to PR poll + reap) when a subprocess is already in-flight.
    dispatchBlock: {
      const defaultMax = runtimeProfile === "local-subprocess" ? 1 : 4;
      const maxConcurrent = config.max_concurrent_executors ?? defaultMax;

      if (runtimeProfile === "local-subprocess") {
        const inFlight = (ports.broker as InMemoryBrokerAdapter).registrySize();
        if (inFlight >= maxConcurrent) {
          emit({ type: "executor_pool_full", in_flight: inFlight, max: maxConcurrent });
          break dispatchBlock;
        }
      } else if (runtimeProfile === "local-docker") {
        if (dockerInFlight >= maxConcurrent) {
          emit({ type: "executor_pool_full", in_flight: dockerInFlight, max: maxConcurrent });
          break dispatchBlock;
        }
      }

    outerLoop:
    for (const watchUrl of config.watches) {
      if (haltedUrls.has(watchUrl)) continue;

      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
      pulledWorkspaceRoots.push(workspaceLocalPath);

      if (!existsSync(workspaceLocalPath)) {
        emit({ type: "workspace_not_found", workspace_url: watchUrl });
        continue;
      }

      let eligibleTasks;
      try {
        eligibleTasks = findEligibleTasks(config, workspaceLocalPath, workflowLocalPath);
      } catch (e) {
        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
        continue;
      }

      if (eligibleTasks.length === 0) {
        emit({ type: "no_eligible_tasks", workspace_url: watchUrl });
        continue;
      }

      for (const { task, featureId } of eligibleTasks) {
        const claimResult = await claimTask({
          workspaceRoot: workspaceLocalPath,
          taskId: task.id,
          featureId,
          gitAuthorEmail,
          gitAuthorName,
          sshKeyPath,
          jitterMaxSeconds: config.jitter_max_seconds,
        });

        const taskBranch = taskBranchName(featureId, task.id);

        if (!claimResult.won) {
          if (claimResult.reason !== "branch_blocked_recovery") {
            emit({ type: "claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
            continue;
          }
          emit({ type: "task_blocked_recovery_detected", task_id: task.id, feature_id: featureId });
        } else {
          emit({ type: "task_claimed", task_id: task.id, feature_id: featureId });
        }

        // ── Open management-repo PR ───────────────────────────────────────────
        if (githubToken) {
          try {
            const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
            await openWorkspacePr({
              workspaceRoot: workspaceLocalPath,
              featureId,
              taskId: task.id,
              branch: taskBranch,
              // Task PRs target the feature branch so all task changes collect
              // there before the Handoff Trigger merges to the base branch (T8).
              baseBranch: featureBranchName(featureId),
              githubToken,
              repoOwner: mgmtCoords.owner,
              repoName: mgmtCoords.repo,
              gitAuthorEmail,
              gitAuthorName,
              sshKeyPath,
            });
            emit({ type: "workspace_pr_opened", task_id: task.id, feature_id: featureId });
          } catch (e) {
            const stderr = (e as { stderr?: Buffer | string }).stderr;
            const stderrStr = stderr instanceof Buffer ? stderr.toString("utf-8") : (stderr ?? "");
            emit({ type: "workspace_pr_failed", task_id: task.id, feature_id: featureId, details: String(e), stderr: stderrStr });
          }
        }

        // ── Resolve model + task repo ────────────────────────────────────────
        const { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel } =
          resolveTaskContext(workspaceLocalPath, featureId, task);

        // ── RAG pre-flight ───────────────────────────────────────────────────
        const mcpRagUrl = process.env.MCP_RAG_URL;
        const workspaceYaml = parseYaml(
          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
        ) as { workspace_id: string };
        const ragQuery = `${task.title} ${featureId}`;
        const ragPreFlight = await fetchRagContext(mcpRagUrl, ragQuery, workspaceYaml.workspace_id);

        try {
          writeRagPreFlight(
            workspaceLocalPath,
            featureId,
            task.id,
            taskBranch,
            gitAuthorEmail,
            gitAuthorName,
            sshKeyPath,
            { query: ragQuery, injected: ragPreFlight.injected, summary: ragPreFlight.summary },
          );
        } catch (e) {
          const details = String(e);
          emit({ type: "rag_pre_flight_failed", task_id: task.id, feature_id: featureId, details });
          mutateTaskYaml({
            workspaceRoot: workspaceLocalPath,
            featureId,
            taskId: task.id,
            taskBranch,
            result: { terminal_status: "failed", blocked_reason: `rag_pre_flight_error: ${details}` },
            gitAuthorEmail,
            gitAuthorName,
            sshKeyPath,
          });
          continue;
        }

        // ── Generate briefing ────────────────────────────────────────────────
        const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
        const baseContext = generateBriefing({
          taskId: task.id,
          featureId,
          taskTitle: task.title,
          taskBranch,
          taskRepo: task.repo,
          taskRepoRoot,
          workspaceRoot: workspaceLocalPath,
          gitAuthorEmail,
          gitAuthorName,
          implementationModel,
          resultPath,
        });
        const briefingContent = ragPreFlight.block
          ? `${baseContext}\n\n${ragPreFlight.block}`
          : baseContext;

        // ── Write briefing via BriefingTransportPort ─────────────────────────
        // Use taskId as the briefing handle so the file path matches the
        // existing briefing-{taskId}/briefing.md convention.
        const briefingPath = await ports.briefing.put(task.id, briefingContent);

        // ── Submit executor (async — T6) ─────────────────────────────────────
        const execHandle = await buildAndSubmitExecutor({
          task, featureId, workspaceId: workspaceYaml.workspace_id,
          taskRepoUrl, taskBranch, taskRepoRoot, implementationModel,
          briefingPath, resultPath, workspaceLocalPath,
        });

        // Persist handle to task YAML for broker crash-recovery reconciliation.
        try {
          await ports.workflowState.persistHandle(workspaceLocalPath, featureId, task.id, execHandle);
        } catch (e) {
          emit({ type: "persist_handle_failed", task_id: task.id, feature_id: featureId, details: String(e) });
        }

        emit({ type: "executor_submitted", task_id: task.id, feature_id: featureId, handle: execHandle });
        if (runtimeProfile === "local-docker") dockerInFlight++;
        outcome = "ran_task";
        break outerLoop;
      }
    }

    // ── Fix-agent dispatch ────────────────────────────────────────────────────
    if (outcome !== "ran_task") {
      fixLoop:
      for (const watchUrl of config.watches) {
        if (haltedUrls.has(watchUrl)) continue;

        const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
        if (!existsSync(workspaceLocalPath)) continue;

        let fixableTasks;
        try {
          fixableTasks = findFixableTasks(config, workspaceLocalPath);
        } catch (e) {
          emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
          continue;
        }

        for (const { task, featureId } of fixableTasks) {
          const taskBranch = taskBranchName(featureId, task.id);
          const claimResult = await claimFixTask({
            workspaceRoot: workspaceLocalPath,
            taskId: task.id,
            featureId,
            gitAuthorEmail,
            gitAuthorName,
            jitterMaxSeconds: config.jitter_max_seconds,
          });

          if (!claimResult.won) {
            emit({ type: "fix_claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
            continue;
          }

          emit({ type: "fix_task_claimed", task_id: task.id, feature_id: featureId });

          const { taskRepoRoot, taskRepoUrl, implementationModel } = resolveTaskContext(workspaceLocalPath, featureId, task);
          const fixWsYaml = parseYaml(
            readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
          ) as { workspace_id: string };

          const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
          const baseContext = generateBriefing({
            taskId: task.id,
            featureId,
            taskTitle: task.title,
            taskBranch,
            taskRepo: task.repo,
            taskRepoRoot,
            workspaceRoot: workspaceLocalPath,
            gitAuthorEmail,
            gitAuthorName,
            implementationModel,
            resultPath,
          });

          const fixBriefingPath = await ports.briefing.put(task.id, baseContext);
          const fixHandle = await buildAndSubmitExecutor({
            task, featureId, workspaceId: fixWsYaml.workspace_id,
            taskRepoUrl, taskBranch, taskRepoRoot: taskRepoRoot, implementationModel,
            briefingPath: fixBriefingPath, resultPath, workspaceLocalPath,
          });
          emit({ type: "fix_executor_submitted", task_id: task.id, feature_id: featureId, handle: fixHandle });
          if (runtimeProfile === "local-docker") dockerInFlight++;
          outcome = "ran_task";
          break fixLoop;
        }
      }
    }

    // ── Reviewer dispatch ─────────────────────────────────────────────────────
    if (outcome !== "ran_task") {
      reviewerLoop:
      for (const watchUrl of config.watches) {
        if (haltedUrls.has(watchUrl)) continue;

        const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
        if (!existsSync(workspaceLocalPath)) continue;

        let reviewableTasks;
        try {
          reviewableTasks = findReviewableTasks(config, workspaceLocalPath);
        } catch (e) {
          emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
          continue;
        }

        for (const { task, featureId } of reviewableTasks) {
          const taskBranch = taskBranchName(featureId, task.id);
          const { taskRepoRoot, taskRepoUrl, implementationModel } = resolveTaskContext(workspaceLocalPath, featureId, task);
          const wsModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
          const revWsYaml = parseYaml(
            readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
          ) as { workspace_id: string };
          let reviewModelOverrides = {};
          try {
            const tMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
            reviewModelOverrides = parseModelOverrides(readFileSync(tMdPath, "utf-8"), task.id);
          } catch { /* non-fatal */ }
          const reviewerModel = resolveModel(wsModelPolicy, reviewModelOverrides, "self_review", task.id);

          const dispatchResult = await dispatchReviewer({
            workspaceRoot: workspaceLocalPath,
            featureId,
            taskId: task.id,
            taskBranch,
            implRepoRoot: taskRepoRoot,
            implRepoUrl: taskRepoUrl,
            gitAuthorEmail,
            gitAuthorName,
            workflowLocalPath,
            maxTurns: config.budget.max_iterations,
            maxTokens: config.budget.max_tokens_per_task,
            logSinkEnabled: config.log_sink.enabled,
            reviewerModel,
            workspaceId: revWsYaml.workspace_id,
            githubToken,
            broker: ports.broker,
            callbackUrl: ports.broker.getCallbackUrl() ?? "",
            emit,
          });

          if (dispatchResult === "dispatched") {
            if (runtimeProfile === "local-docker") dockerInFlight++;
            outcome = "ran_task";
            break reviewerLoop;
          }
        }
      }
    }
    } // end dispatchBlock

    // ── In-review PR poll ─────────────────────────────────────────────────────
    // In local-subprocess mode the executor subprocess shares the same container
    // filesystem as the orchestrator. Both can race on `git rebase` in the same
    // repo — a second rebase operation fails with "rebase-merge directory already
    // exists". Re-check in-flight count here (not just in dispatchBlock) because
    // pulledWorkspaceRoots is already populated on the same cycle that dispatched
    // the executor; the dispatchBlock early-break only fires on *subsequent* cycles.
    const skipPrPoll =
      runtimeProfile === "local-subprocess" &&
      (ports.broker as InMemoryBrokerAdapter).registrySize() > 0;
    if (githubToken && !skipPrPoll) {
      const prPollIntervalMs =
        (config.pr_poll_interval_seconds ?? config.idle_sleep_seconds ?? 60) * 1000;
      const now = Date.now();

      if (lastPrPollAt === null || now - lastPrPollAt >= prPollIntervalMs) {
        if (pulledWorkspaceRoots.length > 0) lastPrPollAt = now;
        try {
          const { prResults, workspacePrRecoveries } = await checkInReviewPrs({
            workspaceRoots: pulledWorkspaceRoots,
            githubToken,
            emit,
          });

          for (const wsRoot of pulledWorkspaceRoots) {
            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
            if (wsResults.some((r) => r.mergeable === false)) {
              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
              const conflictModel = resolveModel(wsModelPolicy, {}, "conflict_resolution", "conflict-resolver");
              await handleMergeConflicts({
                prResults: wsResults,
                workspaceRoot: wsRoot,
                resolveImplRepoRoot: (repoId) => resolveRepoLocalPath(wsRoot, repoId),
                resolveImplBaseBranch: (repoId) => resolveRepoBaseBranch(wsRoot, repoId),
                resolveTaskRepoId: (fId, tId) => resolveTaskRepoId(wsRoot, fId, tId),
                gitAuthorEmail,
                gitAuthorName,
                sshKeyPath,
                emit,
                invokeClaudeForResolution: makeConflictResolver(conflictModel),
              });
            }
          }

          for (const wsRoot of pulledWorkspaceRoots) {
            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
            if (wsResults.some((r) => r.merged === true)) {
              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
              const conflictModel = resolveModel(wsModelPolicy, {}, "conflict_resolution", "conflict-resolver");
              const mgmtCoords = parseManagementRepoCoords(wsRoot);
              await handleMergedPrs({
                prResults: wsResults,
                workspaceRoot: wsRoot,
                mgmtRepoOwner: mgmtCoords.owner,
                mgmtRepoName: mgmtCoords.repo,
                mgmtBaseBranch: mgmtCoords.baseBranch,
                githubToken,
                gitAuthorEmail,
                gitAuthorName,
                sshKeyPath,
                emit,
                invokeClaudeForResolution: makeConflictResolver(conflictModel),
              });
            }
          }

          for (const wsRoot of pulledWorkspaceRoots) {
            const wsRecoveries = workspacePrRecoveries.filter((r) => r.workspaceRoot === wsRoot);
            if (wsRecoveries.length > 0) {
              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
              const conflictModel = resolveModel(wsModelPolicy, {}, "conflict_resolution", "conflict-resolver");
              const mgmtCoords = parseManagementRepoCoords(wsRoot);
              await handleWorkspacePrRecoveries({
                recoveries: wsRecoveries,
                mgmtRepoOwner: mgmtCoords.owner,
                mgmtRepoName: mgmtCoords.repo,
                mgmtBaseBranch: mgmtCoords.baseBranch,
                githubToken,
                gitAuthorEmail,
                gitAuthorName,
                sshKeyPath,
                emit,
                invokeClaudeForResolution: makeConflictResolver(conflictModel),
              });
            }
          }
        } catch (e) {
          emit({ type: "in_review_poll_error", details: String(e) });
        }
      }
    }

    // ── Shared reap loop ──────────────────────────────────────────────────────
    // Drain completions posted by in-flight executors this cycle (and any
    // leftovers from previous cycles). Routes by handle.kind → dispatcher.
    try {
      const reapResult = await runReapLoop({
        broker: ports.broker,
        workspaceRoots: pulledWorkspaceRoots,
        gitAuthorEmail,
        gitAuthorName,
        sshKeyPath,
        githubToken,
        emit,
      });
      if (reapResult.dispatched > 0) {
        if (runtimeProfile === "local-docker") {
          dockerInFlight = Math.max(0, dockerInFlight - reapResult.dispatched);
        }
        emit({ type: "reap_cycle_complete", dispatched: reapResult.dispatched, failed: reapResult.failed });
        if (outcome === "idle") outcome = "ran_task";
      }
    } catch (e) {
      emit({ type: "reap_loop_error", details: String(e) });
    }

    return outcome;
  }

  await runAgentLoop({ config, runCycle: runOneCycle, emit, scheduler: ports.scheduler });
  return 0;
}

main()
  .then((code) => process.exit(code))
  .catch((e) => {
    try {
      console.log(JSON.stringify({
        type: "fatal_error",
        details: (e as Error).message ?? String(e),
        at: new Date().toISOString(),
      }));
    } catch { /* last resort */ }
    process.exit(4);
  });

