/**
 * Tests for briefing/fix-briefing.ts — generateFixBriefing + extractPrUrlFromTask.
 *
 * Test plan:
 *   1. generateFixBriefing — all opts fields appear in the returned string.
 *   2. generateFixBriefing — the string never contains "undefined" or "null".
 *   3. generateFixBriefing — required section headers are present.
 *   4. generateFixBriefing — instructs executor to invoke /respond-to-review.
 *   5. generateFixBriefing — resultPath and prUrl appear in the output.
 *   6. generateFixBriefing — produces different outputs for different taskIds.
 *   7. extractPrUrlFromTask — returns pr.url when no change_requested log entry.
 *   8. extractPrUrlFromTask — prefers pr_url on most recent change_requested log entry.
 *   9. extractPrUrlFromTask — returns null when no pr.url and no matching log entry.
 *  10. extractPrUrlFromTask — walks log in reverse (uses the most recent entry).
 */

import { describe, it, expect } from "vitest";
import {
  generateFixBriefing,
  extractPrUrlFromTask,
  type FixBriefingOpts,
} from "../src/briefing/fix-briefing.js";
import type { Task } from "../src/types/task.js";

// ── Fixtures ─────────────────────────────────────────────────────────────────

const BASE_OPTS: FixBriefingOpts = {
  taskId: "T4",
  featureId: "autonomous-task-orchestrator",
  taskTitle: "Fix agent briefing + dispatch",
  taskBranch: "feature/autonomous-task-orchestrator-T4",
  taskRepo: "workflow",
  taskRepoRoot: "/agent/data/agent-workflow",
  workspaceRoot: "/agent/data/project-workspace",
  prUrl: "https://github.com/org/repo/pull/42",
  gitAuthorEmail: "agent@example.com",
  gitAuthorName: "Workflow Agent",
  implementationModel: "claude-sonnet-4-6",
  resultPath: "/tmp/executor-result-T4.json",
};

function makeTask(overrides: Partial<Task> = {}): Task {
  return {
    id: "T4",
    title: "Fix agent briefing + dispatch",
    repo: "workflow",
    status: "change_requested",
    depends_on: [],
    blocked_reason: null,
    blocked_context: null,
    branch: "feature/autonomous-task-orchestrator-T4",
    execution: {
      actor_type: "agent",
      last_updated_by: null,
      last_updated_at: null,
    },
