  });

  it("contains workspaceRoot", () => {
    expect(generateFixBriefing(BASE_OPTS)).toContain(BASE_OPTS.workspaceRoot);
  });

  it("contains taskRepoRoot", () => {
    expect(generateFixBriefing(BASE_OPTS)).toContain(BASE_OPTS.taskRepoRoot);
  });

  it("contains gitAuthorEmail", () => {
    expect(generateFixBriefing(BASE_OPTS)).toContain(BASE_OPTS.gitAuthorEmail);
  });

  it("contains gitAuthorName", () => {
    expect(generateFixBriefing(BASE_OPTS)).toContain(BASE_OPTS.gitAuthorName);
  });

  it("contains implementationModel", () => {
    expect(generateFixBriefing(BASE_OPTS)).toContain(BASE_OPTS.implementationModel);
  });

  it("contains resultPath", () => {
    expect(generateFixBriefing(BASE_OPTS)).toContain(BASE_OPTS.resultPath);
  });

  it("contains prUrl", () => {
    expect(generateFixBriefing(BASE_OPTS)).toContain(BASE_OPTS.prUrl);
  });

  it("does not contain the literal text 'undefined'", () => {
    expect(generateFixBriefing(BASE_OPTS)).not.toContain("undefined");
